 insert into sources(title,author,publication,url,source_type) values ('Al-Khwārizmī','G. J. Toomer','Dictionary of Scientific Biography, vol. 7, pp. 358–365 (New York: Charles Scribner''s Sons, 1973); read via the St Andrews-hosted copy','https://mathshistory.st-andrews.ac.uk/DSB/Al-Khwarizmi.pdf','academic') returning id into srcid; src:=src||jsonb_build_object('DSB-K',srcid);
 insert into sources(title,author,publication,url,source_type) values ('Khwarizmi: Muhammad ibn Musa','Sonja Brentjes','Biographical Encyclopedia of Astronomers (Springer, 2007)','https://mathshistory.st-andrews.ac.uk/BEA/al_khwarizmi_bea.pdf','academic') returning id into srcid; src:=src||jsonb_build_object('BEA-K',srcid);
 insert into sources(title,author,publication,url,source_type) values ('Banū Mūsā','Josep Casulleras','Biographical Encyclopedia of Astronomers (Springer, 2007)','https://mathshistory.st-andrews.ac.uk/BEA/banu_musa_bea.pdf','academic') returning id into srcid; src:=src||jsonb_build_object('BEA-BM',srcid);
 insert into sources(title,author,publication,url,source_type) values ('al-Kindi','Peter Adamson','Stanford Encyclopedia of Philosophy, first published 1 Dec 2006, substantive revision 25 Apr 2024','https://plato.stanford.edu/ENTRIES/al-kindi/','academic') returning id into srcid; src:=src||jsonb_build_object('SEP-K',srcid);
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('fa4c9fb1-03c2-55c8-a642-e7fd250d0d09',(ids->>'al-khwarizmi')::uuid,'A compendium that reduces first- and second-degree problems to six standard forms using ''completion'' (al-jabr) and ''balancing'' (al-muqabala), with worked applications to mensuration, trade and inheritance, written entirely in words. Reported as the first known algebra work in Arabic.','Algebra treatise: systematic reduction to standard forms','mathematical_development','high',did,'813–833','Greek and Hindu algebraic knowledge, which had advanced further in places but did not resemble this presentation (DSB).','A practical, systematic handbook that fixed the terminology and form later Arabic algebra and Latin translations used. Not the first algebra, and the source of its methods is disputed (K-12).','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('fa4c9fb1-03c2-55c8-a642-e7fd250d0d09',(src->>'DSB-K')::uuid,'entry: the Algebra','academic_research');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('fa4c9fb1-03c2-55c8-a642-e7fd250d0d09',(src->>'BEA-K')::uuid,'entry: works','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('83d85f9a-56e9-5e8b-86b0-590a7e8bbe8d',(ids->>'al-khwarizmi')::uuid,'An arithmetic treatise using the digits 1–9, zero and the place-value system, preserved only in Latin; DSB thinks he was probably the first to expound the decimal system systematically in Arabic.','Exposition of the Hindu numerals and place value','commentary_or_synthesis','medium',did,'after the Algebra','The Hindu numerals and decimal place value reached Baghdad from India; alphabetic and sexagesimal systems were in use (DSB).','A systematic exposition for Arabic readers. DSB hedges (''likely enough''); the Arabic original is lost and the Latin text may be altered. Not a claim that he invented the numerals.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('83d85f9a-56e9-5e8b-86b0-590a7e8bbe8d',(src->>'DSB-K')::uuid,'entry: Hindu numerals','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('aff01f46-0918-5f0b-be1a-e33a5bd212fb',(ids->>'al-khwarizmi')::uuid,'A set of astronomical tables and rules revising the Zij al-Sindhind, mixing Indian, Sasanian and Ptolemaic elements; the original is lost and known only through later revisions.','Zij: revision of the Sindhind astronomical tradition','commentary_or_synthesis','medium',did,'813–833','Earlier Zij al-Sindhind handbooks (BEA names al-Fazari), the Zij al-Shah and Ptolemy''s tables (DSB, BEA).','A revision for al-Ma''mun that spread Indian astronomical methods and, via Latin, reached Europe. Whether it contains original observations is disputed (K-17).','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('aff01f46-0918-5f0b-be1a-e33a5bd212fb',(src->>'DSB-K')::uuid,'entry: the zij','academic_research');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('aff01f46-0918-5f0b-be1a-e33a5bd212fb',(src->>'BEA-K')::uuid,'entry: the zij','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('c7782d75-168c-547d-b437-30359b05a505',(ids->>'al-khwarizmi')::uuid,'A list of latitudes and longitudes of places grouped by climate zone, related to but different from Ptolemy''s Geography, with a shorter Mediterranean and errors of its own.','Geography: coordinate tables of the known world','commentary_or_synthesis','medium',did,'after 816–817 (tentative)','Ptolemy''s Geography and probably al-Ma''mun''s world map (a conjecture, DSB).','A more accurate map than Ptolemy''s for Islamic lands according to DSB; unknown in Europe until the 19th century.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('c7782d75-168c-547d-b437-30359b05a505',(src->>'DSB-K')::uuid,'entry: the Geography','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('29a1d0c9-153b-5096-8588-ef059dc7804e',(ids->>'banu-musa')::uuid,'A work on mechanical devices attributed to the three brothers jointly; BEA says their mechanics marks significant advances over Philo of Byzantium and Hero of Alexandria. Device-level details need Hill''s translation.','Mechanical devices (Kitab al-hiyal)','technical_improvement','medium',did,'9th century','The works of Philo and Hero, extensively known to Muslim engineers (BEA).','BEA''s judgement only; individual devices and inventors are not established from the sources read (popular claims are UNVERIFIED, B-12).','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('29a1d0c9-153b-5096-8588-ef059dc7804e',(src->>'BEA-BM')::uuid,'entry: mechanics','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('9021e4b3-0989-5300-989f-a798518dcd45',(ids->>'banu-musa')::uuid,'A geometry treatise on measuring plane and spherical figures, attributed to the brothers jointly.','Book on the Measurement of Plane and Spherical Figures','mathematical_development','medium',did,'9th century','Greek geometry, including Archimedes and Apollonius, available in Arabic (BEA mentions Apollonius in related works).','BEA calls it one of the fundamental medieval geometry texts: recast by al-Tusi, translated by Gerard of Cremona, and reflected in later authors.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('9021e4b3-0989-5300-989f-a798518dcd45',(src->>'BEA-BM')::uuid,'entry: mathematics','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('ebba9a06-2820-599c-b1bc-5d77bd2842b8',(ids->>'banu-musa')::uuid,'The brothers funded the search for Greek manuscripts in Byzantium and employed translators, including Thabit ibn Qurra and Hunayn ibn Ishaq (per BEA).','Sponsoring the acquisition and translation of classical works','translation_or_preservation','medium',did,'9th century','Greek scientific texts not yet in Arabic.','BEA credits them with greatly promoting the translation movement; details on specific books are not given.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('ebba9a06-2820-599c-b1bc-5d77bd2842b8',(src->>'BEA-BM')::uuid,'entry: background','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('d8fabdc1-229f-5f33-a4f3-598f68f5c6c0',(ids->>'muhammad-ibn-musa-ibn-shakir')::uuid,'Attributed to Muhammad: a book arguing that the daily motion of the heavens comes from rotation of all spheres, denying the ninth sphere that moves them in Ptolemy''s scheme.','Critique of the Ptolemaic ninth sphere','theoretical_contribution','medium',did,'9th century','Ptolemy''s nine-sphere scheme.','A historical argument within Ptolemaic cosmology. Not a claim about modern astronomy (M-B1).','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('d8fabdc1-229f-5f33-a4f3-598f68f5c6c0',(src->>'BEA-BM')::uuid,'entry: astronomy','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('09f3e909-87a4-5e3d-89da-353032c24906',(ids->>'ahmad-ibn-musa-ibn-shakir')::uuid,'Reportedly by Ahmad: a geometric demonstration that no sphere exists beyond the sphere of the fixed stars.','Geometric proof against a ninth sphere (reported)','theoretical_contribution','low',did,'9th century','Ptolemy''s ninth sphere.','Reported attribution only (BEA words it ''reportedly''); the text is not known to survive.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('09f3e909-87a4-5e3d-89da-353032c24906',(src->>'BEA-BM')::uuid,'entry: astronomy','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('00abce26-d8e1-5a7f-8c54-f0a4e27fc7d1',(ids->>'al-kindi')::uuid,'A treatise adapting Greek, especially Philoponus'' and Neoplatonic, arguments to argue the world began and that God is a simple ''true One'', dedicated to al-Mu''tasim.','On First Philosophy: Greek arguments for a created world and a simple God','commentary_or_synthesis','high',did,'833–842','Aristotle, Neoplatonic texts and Philoponus'' arguments against eternity (SEP).','Presented as Arabic philosophy''s first systematic metaphysics in SEP''s characterisation (Q-15), but its argument for a beginning follows Philoponus.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('00abce26-d8e1-5a7f-8c54-f0a4e27fc7d1',(src->>'SEP-K')::uuid,'§1.2','academic_research');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('00abce26-d8e1-5a7f-8c54-f0a4e27fc7d1',(src->>'SEP-K')::uuid,'§3.3','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('b4f098f0-f948-5e77-b6c8-92fec6218cec',(ids->>'al-kindi')::uuid,'He led one of two main translation groups, whose output included the Theology of Aristotle and other Greek works, mediating between patrons and translators.','Leading a translation circle','translation_or_preservation','medium',did,'9th century','Greek philosophy and science not yet in Arabic.','The extent of his own translating versus organizing is not settled in the source (''seems to have been a mediator'').','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('b4f098f0-f948-5e77-b6c8-92fec6218cec',(src->>'SEP-K')::uuid,'§1.1','academic_research');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('b4f098f0-f948-5e77-b6c8-92fec6218cec',(src->>'SEP-K')::uuid,'§6','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('1441df13-e94f-58a2-a752-0d883671d97c',(ids->>'al-kindi')::uuid,'Optical work (On Perspectives, Latin only) using geometry and the Euclid–Ptolemy tradition, including criticism of Euclid''s theory of vision.','Geometric optics and critique of Euclid','commentary_or_synthesis','medium',did,'9th century','Euclid''s and Ptolemy''s optics (vision by rays from the eye).','Followed the emission model, later superseded; Ibn al-Haytham explained vision accurately some decades later (SEP).','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('1441df13-e94f-58a2-a752-0d883671d97c',(src->>'SEP-K')::uuid,'§5.1','academic_research');
 insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ('3a3b98d6-7e45-5e0e-aa50-4326cdf97784',(ids->>'al-kindi')::uuid,'A Latin-only treatise explaining physical and astral interaction by rays; its authorship is contested.','On Rays (authenticity disputed)','disputed_attribution','uncertain',did,'9th century','Euclidean ray geometry.','SEP notes a strong case against his authorship (Matton 2022) while allowing it may rest on authentic material.','under_review');
 insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ('3a3b98d6-7e45-5e0e-aa50-4326cdf97784',(src->>'SEP-K')::uuid,'§5.1','academic_research');
 insert into works(scholar_id,original_title,alt_spellings,original_language,subject,authorship_status,publication_note) values ((ids->>'al-khwarizmi')::uuid,'al-Kitab al-mukhtasar fi hisab al-jabr wa''l-muqabala',array['Hisab al-jabr wa''l-muqabala','The Algebra']::text[],'Arabic (per the sources'' titles); not otherwise stated','Algebra, mensuration, inheritance problems','academically_supported','Date: composed under al-Ma''mun (813–833) (DSB-K, BEA-K). Editions per DSB-K: Rosen (Arabic and English, London 1831, called careless); Mashrafa and Ahmad (Cairo 1939); Latin by Robert of Chester (ed. Karpinski 1915) and a Latin version probably by Gerard of Cremona. Manuscripts: Both Rosen''s and the Cairo edition rest on Oxford, Bodleian I 918, 1 (as printed in DSB-K); other manuscripts exist, e.g. Berlin 5955 no. 6, ff. 60r–95v (reported in DSB-K via Anbouba). Shelfmarks as printed in DSB-K, not independently checked.') returning id into wid;
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'DSB-K')::uuid,'entry: the Algebra','academic_research');
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'BEA-K')::uuid,'entry: works','academic_research');
 insert into works(scholar_id,original_title,alt_spellings,original_language,subject,authorship_status,publication_note) values ((ids->>'al-khwarizmi')::uuid,'Hindu-numerals arithmetic (Arabic title uncertain)',array['Kitab hisab al-''adad al-hindi (possible)','Kitab al-jam'' wa''l-tafriq bi hisab al-hind (possible)']::text[],'Arabic (per the sources'' titles); not otherwise stated','Arithmetic with Hindu numerals','academically_supported','Date: after the Algebra (DSB-K, BEA-K). Arabic text lost; survives in Latin (editions: Boncompagni 1857; Vogel 1963, per DSB-K). Manuscripts: Unique Latin manuscript (DSB-K); no shelfmark recorded.') returning id into wid;
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'DSB-K')::uuid,'entry: Hindu numerals','academic_research');
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'BEA-K')::uuid,'entry: works','academic_research');
 insert into works(scholar_id,original_title,alt_spellings,original_language,subject,authorship_status,publication_note) values ((ids->>'al-khwarizmi')::uuid,'Zij al-Sindhind',array['Zij of al-Khwarizmi','Astronomical tables']::text[],'Arabic (per the sources'' titles); not otherwise stated','Astronomical tables (Indian, Sasanian, Ptolemaic elements)','academically_supported','Date: under al-Ma''mun (813–833) (DSB-K, BEA-K). Original lost; known through Latin of al-Majriti''s revision (edited by Suter 1914; Neugebauer 1962, per DSB-K and BEA-K). Manuscripts: Latin manuscripts of the revision exist (DSB-K); no shelfmarks recorded') returning id into wid;
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'DSB-K')::uuid,'entry: the zij','academic_research');
 insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'BEA-K')::uuid,'entry: the zij','academic_research');
